// AWI SEO: halaman /slider/ bawaan tema tipis -> noindex & keluar dari sitemap (Claude 30 Okt 2026)
add_filter( 'wpseo_robots', function ( $robots ) {
	if ( is_singular( 'slider' ) || is_post_type_archive( 'slider' ) ) {
		return 'noindex, follow';
	}
	return $robots;
}, 20 );
add_filter( 'wpseo_sitemap_exclude_post_type', function ( $exclude, $post_type ) {
	return 'slider' === $post_type ? true : $exclude;
}, 10, 2 );
